    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "No job is assigned to you yet. As soon as the owner or the office assigns you a job, it appears here.",
    "Donnerstag": "Thursday",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "You lose access to all jobs and customers of this business. Your notes stay there. Your account remains: you can start your own business or join another.",
