    "Ein Angebot ist keine Rechnung.": "A quote is not an invoice.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "A business cannot be deleted with one tap: invoices must be kept by law for years (GoBD). If you want to close your business or delete your account, please contact support. You can remove employees under \"Team\".",
