    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Kişi Zunft'u yükler, kendi e-postasıyla kayıt olur ve bu kodu tarar (veya yazar).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Kişi hemen işletmeden çıkarılır. Notları korunur. Kontenjan boşalır.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Kişi işletmenle olan tüm bağlantısını hemen kaybeder: iş yok, müşteri yok, veri yok. Önceki notları işlerde (adıyla) kalır. Hesap ona aittir: kendi işletmesini kurabilir veya başkasına katılabilir. Kontenjan boşalır.",
    "Die Rechnung hat keine Positionen.": "Faturada kalem yok.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Fatura zaten ödendi olarak işaretlenmiş. Lütfen önce mali müşavirle nasıl düzeltileceğini görüş.",
    "Die Rechnung konnte nicht storniert werden.": "Fatura iptal edilemedi.",
    "Die Verarbeitung ist fehlgeschlagen.": "İşlem başarısız oldu.",
    "Dienstag": "Salı",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Bu not hiçbir işe ait değil. Lütfen at ve yeniden kaydet.",
    "Diese Rechnung wurde schon storniert.": "Bu fatura zaten iptal edildi.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Bu süre zaten faturalandı ve silinemez.",
    "Diesen Kunden gibt es schon": "Bu müşteri zaten var",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Bu iş faturalandı. Artık not kaydedilemez.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Bu iş kapatıldı. Artık not kaydedilemez.",
    "Dieser Kunde existiert nicht mehr.": "Bu müşteri artık yok.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Bu müşterinin teklifleri veya faturaları var ve silinemez (yasal saklama).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Bu telefon bildirimler için adres alamadı. Lütfen daha sonra tekrar dene.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Bu PDF okunur ve fiş olarak kaydedilir.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Henüz sana bir iş atanmadı. İşletme sahibi veya ofis sana bir iş atar atmaz burada görünür.",
    "Donnerstag": "Perşembe",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Bu işletmenin tüm işlerine ve müşterilerine erişimini kaybedersin. Notların orada kalır. Hesabın durur: kendi işletmeni kurabilir veya başkasına katılabilirsin.",
    "E-Mail (Betrieb)": "E-posta (işletme)",
    "E-Mail oder Passwort ist falsch.": "E-posta veya şifre yanlış.",
    "E-Rechnung": "E-fatura",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Teklif bir fatura değildir.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Bir işletme tek dokunuşla silinemez: faturalar yasa gereği yıllarca saklanmalıdır (GoBD). İşletmeni kapatmak veya hesabını silmek istersen lütfen destekle iletişime geç. Çalışanları \"Ekip\" altından çıkarabilirsin.",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Bir kayıt en fazla 24 saat sürebilir.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Bir randevu en fazla 31 gün sürebilir.",
