    "Erstellt": "Düzenlendi",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Bu faturayı iptal eden, kendi numarası olan bir iptal faturası oluşturulur. Fatura değişmeden kayıtlı kalır ve \"İptal edildi\" olarak işaretlenir.\n\nİşin notları yeniden serbest kalır. Sonra işi tekrar kontrol edip düzeltebilir ve yeni bir fatura oluşturabilirsin.\n\nBu geri alınamaz.",
    "Es wurde nichts aufgenommen.": "Hiçbir şey kaydedilmedi.",
