    "Daten werden gesammelt...": "Veriler toplanıyor...",
    "Du bekommst eine ZIP-Datei mit Kunden, Aufträgen, Notizen (als Text), allen Rechnungen und Angeboten mit PDF, den Einkaufsbelegen mit Fotos, Terminen und Arbeitszeiten. Das dauert je nach Menge eine Weile und braucht Internet. Bewahre die Datei sicher auf: sie enthält Daten deiner Kunden.": "Müşteriler, işler, notlar (metin olarak), PDF'li tüm faturalar ve teklifler, fotoğraflı alış fişleri, randevular ve çalışma süreleri içeren bir ZIP dosyası alırsın. Miktara bağlı olarak biraz sürer ve internet gerekir. Dosyayı güvende tut: müşterilerinin verilerini içerir.",
