    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "هذا ينشئ منشأة جديدة تملكها. هل دعاك رئيسك؟ إذن ارجع واختر \"تمت دعوتي\".",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "لم يكن ذلك ممكناً (لم يعد مُسنداً؟).",
    "Datum": "التاريخ",
    "Davon": "منها",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "يعرض لك رئيسك في التطبيق ضمن \"المنشأة ← الفريق\" رمز QR ورمزاً من 8 أحرف. امسح رمز QR أو اكتب الرمز.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "سيتم حذف حسابك ووصولك. لا يمكن التراجع عن ذلك. تبقى الملاحظات التي سجلتها لمنشأة ما هناك مع المهمة (اسمك فقط كنص).",
    "Deine erfasste Arbeitszeit": "وقت عملك المسجّل",
    "Der Anruf konnte nicht gestartet werden.": "تعذّر بدء المكالمة.",
    "Der Auftrag dieser Notiz existiert nicht mehr.": "مهمة هذه الملاحظة لم تعد موجودة.",
    "Der Auftrag existiert nicht mehr": "المهمة لم تعد موجودة",
    "Der Beleg konnte nicht gespeichert werden.": "تعذّر حفظ الإيصال.",
    "Der Code besteht aus 8 Zeichen (Buchstaben und Ziffern).": "يتكون الرمز من 8 أحرف (حروف وأرقام).",
    "Der Code ist ungültig, abgelaufen oder schon benutzt. Bitte beim Chef einen neuen Code holen.": "الرمز غير صالح أو منتهي أو مستخدم من قبل. يرجى طلب رمز جديد من رئيسك.",
    "Der Code {0} funktioniert danach nicht mehr.": "الرمز {0} لن يعمل بعد ذلك.",
    "Der Export ist fehlgeschlagen. Bitte Internetverbindung prüfen und erneut versuchen.": "فشل التصدير. يرجى التحقق من اتصال الإنترنت والمحاولة مرة أخرى.",
    "Der Kunde existiert nicht mehr": "العميل لم يعد موجوداً",
    "Der Kunde existiert nicht mehr.": "العميل لم يعد موجوداً.",
    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "رفض الخادم الطلب. يرجى المحاولة لاحقاً.",
    "Der Server ist gerade nicht erreichbar.": "الخادم غير متاح حالياً.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "مساحة التخزين في باقتك ممتلئة. لتسجيلات وإيصالات جديدة تحتاج إلى باقة أكبر.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "مساحة التخزين شبه ممتلئة. لمزيد من المساحة تحتاج إلى باقة أكبر.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "مساحة التخزين ممتلئة: يتم رفض التسجيلات والإيصالات الجديدة. لمزيد من المساحة تحتاج إلى باقة أكبر. لا يزال بالإمكان إنشاء الفواتير.",
    "Der Status konnte nicht geändert werden.": "تعذّر تغيير الحالة.",
    "Der Upload wurde abgelehnt.": "تم رفض الرفع.",
    "Der laufende Timer für „{0}“ wurde beendet ({1} Std).": "تم إيقاف المؤقت الجاري لـ \"{0}\" ({1} ساعة).",
    "Deutsche IBAN hat 22 Zeichen": "رقم IBAN الألماني يتكون من 22 حرفاً",
    "Dezember": "ديسمبر",
    "Die Aufnahme konnte nicht abgespielt werden.": "تعذّر تشغيل التسجيل.",
    "Die Aufnahme konnte nicht geladen werden. Bitte Internetverbindung prüfen.": "تعذّر تحميل التسجيل. يرجى التحقق من اتصال الإنترنت.",
    "Die Aufnahme konnte nicht gespeichert werden.": "تعذّر حفظ التسجيل.",
    "Die Aufnahme konnte nicht gestartet werden.": "تعذّر بدء التسجيل.",
    "Die Aufnahme war zu kurz.": "كان التسجيل قصيراً جداً.",
    "Die Belege konnten nicht geladen werden.": "تعذّر تحميل الإيصالات.",
    "Die Bestätigung hat nicht geklappt. Die App-Sperre bleibt aus.": "لم ينجح التأكيد. يبقى قفل التطبيق معطلاً.",
    "Die Betriebsdaten werden noch geladen.": "بيانات المنشأة لا تزال قيد التحميل.",
