    "Die Datei wurde abgelehnt.": "تم رفض الملف.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "إذن الإشعارات مفقود. يرجى السماح لـ Zunft في إعدادات الهاتف.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "الكاميرا غير متاحة. يرجى السماح بالوصول في الإعدادات أو كتابة الرمز يدوياً.",
    "Die Karte konnte nicht geöffnet werden.": "تعذّر فتح الخريطة.",
    "Die Notiz ist zu lang (höchstens {0} Zeichen).": "الملاحظة طويلة جداً (بحد أقصى {0} حرفاً).",
    "Die Notiz kann nicht mehr entfernt werden (bereits abgerechnet?).": "لا يمكن إزالة الملاحظة بعد الآن (تمت محاسبتها؟).",
    "Die Notiz konnte nicht gespeichert werden.": "تعذّر حفظ الملاحظة.",
