    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "تعذّر تحميل الملاحظات. يرجى التحقق من اتصال الإنترنت.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "يجب أن تكون الاستراحة أقصر من وقت العمل.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "يحصل الشخص على الوصول مجدداً (ويشغل مقعداً).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "يثبّت الشخص Zunft ويسجّل ببريده الإلكتروني ويمسح هذا الرمز (أو يكتبه).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "يخرج الشخص فوراً من المنشأة. تبقى ملاحظاته. يصبح المقعد شاغراً.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "يفقد الشخص فوراً كل صلة بمنشأتك: لا مهام ولا عملاء ولا بيانات. تبقى ملاحظاته السابقة مع المهام (باسمه). الحساب يخصه: يمكنه إنشاء منشأته أو الانضمام إلى أخرى. يصبح المقعد شاغراً.",
    "Die Rechnung hat keine Positionen.": "الفاتورة لا تحتوي على بنود.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "الفاتورة معلّمة بالفعل كمدفوعة. يرجى أولاً توضيح كيفية تصحيحها مع المحاسب الضريبي.",
    "Die Rechnung konnte nicht storniert werden.": "تعذّر إلغاء الفاتورة.",
    "Die Verarbeitung ist fehlgeschlagen.": "فشلت المعالجة.",
    "Dienstag": "الثلاثاء",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "هذه الملاحظة لا تنتمي إلى أي مهمة. يرجى تجاهلها والتسجيل من جديد.",
    "Diese Rechnung wurde schon storniert.": "تم إلغاء هذه الفاتورة بالفعل.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "تمت محاسبة هذا الوقت ولا يمكن حذفه.",
    "Diesen Kunden gibt es schon": "هذا العميل موجود بالفعل",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "تمت محاسبة هذه المهمة. لا يمكن تسجيل ملاحظات أخرى.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "هذه المهمة مغلقة. لا يمكن تسجيل ملاحظات أخرى.",
    "Dieser Kunde existiert nicht mehr.": "هذا العميل لم يعد موجوداً.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "لهذا العميل عروض أسعار أو فواتير ولا يمكن حذفه (حفظ قانوني).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "لم يحصل هذا الهاتف على عنوان للإشعارات. يرجى المحاولة لاحقاً.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "تتم قراءة ملف PDF هذا وحفظه كإيصال.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "لم تُسند إليك أي مهمة بعد. بمجرد أن يسند المالك أو المكتب مهمة إليك ستظهر هنا.",
    "Donnerstag": "الخميس",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "ستفقد الوصول إلى جميع مهام وعملاء هذه المنشأة. تبقى ملاحظاتك هناك. يبقى حسابك: يمكنك إنشاء منشأتك أو الانضمام إلى أخرى.",
    "E-Mail (Betrieb)": "البريد الإلكتروني (المنشأة)",
    "E-Mail oder Passwort ist falsch.": "البريد الإلكتروني أو كلمة المرور غير صحيحة.",
    "E-Rechnung": "فاتورة إلكترونية",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "عرض السعر ليس فاتورة.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "لا يمكن حذف منشأة بنقرة واحدة: يجب حفظ الفواتير قانونياً لسنوات (GoBD). إذا أردت إغلاق منشأتك أو حذف حسابك فيرجى التواصل مع الدعم. يمكنك إزالة الموظفين ضمن \"الفريق\".",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "لا يجوز أن يستغرق الإدخال أكثر من 24 ساعة.",
    "Ein Termin darf höchstens 31 Tage dauern.": "لا يجوز أن يستغرق الموعد أكثر من 31 يوماً.",
