    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "اقتربنا من الانتهاء: أرسلنا إليك رسالة بريد إلكتروني. يرجى تأكيد العنوان ثم تسجيل الدخول.",
