    "Für die E-Rechnung braucht der Kunde eine vollständige Anschrift (Straße, PLZ, Ort).": "للفاتورة الإلكترونية يحتاج العميل إلى عنوان كامل (الشارع، الرمز البريدي، المدينة).",
    "Für die E-Rechnung fehlt die IBAN des Betriebs (Betrieb → Bearbeiten).": "رقم IBAN للمنشأة مفقود للفاتورة الإلكترونية (المنشأة ← تعديل).",
    "Für die E-Rechnung fehlt die Steuernummer oder USt-IdNr. des Betriebs.": "الرقم الضريبي أو رقم ضريبة القيمة المضافة للمنشأة مفقود للفاتورة الإلكترونية.",
    "Für die E-Rechnung fehlt die vollständige Anschrift des Betriebs.": "العنوان الكامل للمنشأة مفقود للفاتورة الإلكترونية.",
