    "In den Notizen steht außerdem Arbeitszeit: {0} Std. Sonst würde sie doppelt berechnet.": "تحتوي الملاحظات أيضاً على وقت عمل: {0} ساعة. وإلا فسيتم احتسابه مرتين.",
    "In der Notiz genannt: \"{0}\" - übernehmen?": "مذكور في الملاحظة: \"{0}\" - تطبيق؟",
    "In diesem Monat ist keine Zeit erfasst.": "لا يوجد وقت مسجّل في هذا الشهر.",
    "In dieser Woche ist keine Zeit erfasst.": "لا يوجد وقت مسجّل في هذا الأسبوع.",
