    "Ist alles scharf und vollständig zu lesen, auch die Summe? Sonst lieber neu aufnehmen.": "هل كل شيء واضح ومقروء بالكامل، بما في ذلك الإجمالي؟ وإلا فالأفضل التسجيل من جديد.",
