    "Keine Verbindung. Bitte Internet prüfen und erneut versuchen.": "لا يوجد اتصال. يرجى التحقق من الإنترنت والمحاولة مرة أخرى.",
    "Keine Verbindung. Bitte später erneut versuchen.": "لا يوجد اتصال. يرجى المحاولة لاحقاً.",
