    "Keine Verbindung. Der Status kann nur online geändert werden.": "لا يوجد اتصال. لا يمكن تغيير الحالة إلا عبر الإنترنت.",
    "Keine Verbindung. Zum Abhaken wird Internet gebraucht.": "لا يوجد اتصال. وضع علامة الإنجاز يحتاج إلى إنترنت.",
    "Keine Verbindung. Zum Einschalten wird Internet gebraucht.": "لا يوجد اتصال. التشغيل يحتاج إلى إنترنت.",
    "Keine Verbindung. Zum Fertigstellen wird Internet gebraucht, weil die Nummer vom Server vergeben wird. Deine Änderungen bleiben erhalten - bitte später noch einmal versuchen.": "لا يوجد اتصال. الإنهاء يحتاج إلى إنترنت لأن الرقم يُمنح من الخادم. تبقى تغييراتك محفوظة - يرجى المحاولة لاحقاً.",
    "Konto erstellen": "إنشاء حساب",
    "Kunde bearbeiten": "تعديل العميل",
