    "Alle Aufträge wandern zum bleibenden Kunden. Fehlende Angaben werden ergänzt, abweichende Angaben stehen danach in den Notizen. Bereits erstellte Angebote und Rechnungen bleiben unverändert (sie müssen laut Gesetz so aufbewahrt werden).": "Të gjitha punët kalojnë te klienti që mbetet. Të dhënat që mungojnë plotësohen, ato të ndryshme vendosen më pas te shënimet. Ofertat dhe faturat e lëshuara mbeten të pandryshuara (ligji kërkon t'i ruash ashtu siç janë).",
