    "Das ist kein Einladungscode von Zunft.": "Ky nuk është kod ftese nga Zunft.",
    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Kjo krijon një biznes të RI që e ke ti. Të ftoi shefi yt? Atëherë kthehu mbrapa dhe zgjidh \"Më ftuan\".",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "Kjo nuk ishte e mundur (nuk të është caktuar më?).",
    "Datum": "Data",
    "Davon": "Nga to",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Shefi yt të tregon në aplikacion te \"Biznesi → Ekipi\" një kod QR dhe një kod me 8 karaktere. Skano kodin QR ose shkruaj kodin.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Llogaria dhe qasja jote do të fshihen. Kjo nuk kthehet mbrapsht. Shënimet që ke regjistruar për një biznes mbeten aty te puna (vetëm emri yt si tekst).",
