    "Der Code besteht aus 8 Zeichen (Buchstaben und Ziffern).": "Kodi përbëhet nga 8 karaktere (shkronja dhe shifra).",
    "Der Code ist ungültig, abgelaufen oder schon benutzt. Bitte beim Chef einen neuen Code holen.": "Kodi është i pavlefshëm, ka skaduar ose është përdorur tashmë. Merr një kod të ri nga shefi.",
    "Der Code {0} funktioniert danach nicht mehr.": "Kodi {0} nuk funksionon më pas.",
    "Der Export ist fehlgeschlagen. Bitte Internetverbindung prüfen und erneut versuchen.": "Eksporti dështoi. Kontrolloni lidhjen me internetin dhe provoni përsëri.",
    "Der Kunde existiert nicht mehr": "Klienti nuk ekziston më",
    "Der Kunde existiert nicht mehr.": "Klienti nuk ekziston më.",
    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "Serveri e refuzoi kërkesën. Provo përsëri më vonë.",
    "Der Server ist gerade nicht erreichbar.": "Serveri nuk është i arritshëm tani.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Hapësira ruajtëse e paketës tënde është plot. Për regjistrime dhe fatura të reja nevojitet një paketë më e madhe.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Hapësira ruajtëse është pothuajse plot. Për më shumë hapësirë nevojitet një paketë më e madhe.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Hapësira ruajtëse është plot: regjistrimet dhe faturat e reja refuzohen. Për më shumë hapësirë nevojitet një paketë më e madhe. Faturat mund të krijohen ende.",
    "Der Status konnte nicht geändert werden.": "Statusi nuk u ndryshua dot.",
    "Der Upload wurde abgelehnt.": "Ngarkimi u refuzua.",
    "Der laufende Timer für „{0}“ wurde beendet ({1} Std).": "Kohëmatësi në punë për \"{0}\" u ndal ({1} orë).",
    "Deutsche IBAN hat 22 Zeichen": "IBAN-i gjerman ka 22 karaktere",
    "Dezember": "Dhjetor",
    "Die Aufnahme konnte nicht abgespielt werden.": "Regjistrimi nuk u luajt dot.",
    "Die Aufnahme konnte nicht geladen werden. Bitte Internetverbindung prüfen.": "Regjistrimi nuk u ngarkua dot. Kontrolloni lidhjen me internetin.",
