    "Die Aufnahme konnte nicht gestartet werden.": "Regjistrimi nuk u nis dot.",
    "Die Aufnahme war zu kurz.": "Regjistrimi ishte shumë i shkurtër.",
    "Die Belege konnten nicht geladen werden.": "Faturat nuk u ngarkuan dot.",
    "Die Bestätigung hat nicht geklappt. Die App-Sperre bleibt aus.": "Konfirmimi nuk funksionoi. Kyçja e aplikacionit mbetet e çaktivizuar.",
    "Die Betriebsdaten werden noch geladen.": "Të dhënat e biznesit po ngarkohen ende.",
    "Die Datei ist zu groß.": "Skedari është shumë i madh.",
    "Die Datei wurde abgelehnt.": "Skedari u refuzua.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Mungon leja për njoftime. Lejoje për Zunft te cilësimet e telefonit.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Kamera nuk është e disponueshme. Lejo qasjen te cilësimet ose shkruaj kodin me dorë.",
    "Die Karte konnte nicht geöffnet werden.": "Harta nuk u hap dot.",
    "Die Notiz ist zu lang (höchstens {0} Zeichen).": "Shënimi është shumë i gjatë (më së shumti {0} karaktere).",
    "Die Notiz kann nicht mehr entfernt werden (bereits abgerechnet?).": "Shënimi nuk mund të hiqet më (është faturuar tashmë?).",
    "Die Notiz konnte nicht gespeichert werden.": "Shënimi nuk u ruajt dot.",
    "Die Notiz konnte nicht verarbeitet werden.": "Shënimi nuk u përpunua dot.",
    "Die Notizen konnten nicht geladen werden.": "Shënimet nuk u ngarkuan dot.",
    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "Shënimet nuk u ngarkuan dot. Kontrolloni lidhjen me internetin.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "Pushimi duhet të jetë më i shkurtër se koha e punës.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "Personi merr sërish qasje (dhe zë një vend).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Personi instalon Zunft, regjistrohet me e-mailin e vet dhe skanon këtë kod (ose e shkruan).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Personi hiqet menjëherë nga biznesi. Shënimet e tij mbeten. Vendi lirohet.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Personi humbet menjëherë çdo lidhje me biznesin tënd: pa punë, pa klientë, pa të dhëna. Shënimet e tij të mëparshme mbeten te punët (me emrin e tij). Llogaria i përket atij: mund të krijojë biznesin e vet ose të bashkohet me një tjetër. Vendi lirohet.",
    "Die Rechnung hat keine Positionen.": "Fatura nuk ka pozicione.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Fatura është shënuar tashmë si e paguar. Sqaro së pari me kontabilistin si korrigjohet.",
    "Die Rechnung konnte nicht storniert werden.": "Fatura nuk u anulua dot.",
    "Die Verarbeitung ist fehlgeschlagen.": "Përpunimi dështoi.",
    "Dienstag": "E martë",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Ky shënim nuk i përket asnjë pune. Hidhe poshtë dhe regjistro përsëri.",
    "Diese Rechnung wurde schon storniert.": "Kjo faturë është anuluar tashmë.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Kjo kohë është faturuar tashmë dhe nuk mund të fshihet.",
    "Diesen Kunden gibt es schon": "Ky klient ekziston tashmë",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Kjo punë është faturuar. Nuk mund të regjistrohen më shënime.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Kjo punë është mbyllur. Nuk mund të regjistrohen më shënime.",
    "Dieser Kunde existiert nicht mehr.": "Ky klient nuk ekziston më.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Ky klient ka oferta ose fatura dhe nuk mund të fshihet (ruajtje ligjore).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Ky telefon nuk mori adresë për njoftime. Provo përsëri më vonë.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Ky PDF lexohet dhe ruhet si faturë blerjeje.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Ende nuk të është caktuar asnjë punë. Sapo pronari ose zyra të caktojë një punë, shfaqet këtu.",
    "Donnerstag": "E enjte",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Humbet qasjen te të gjitha punët dhe klientët e këtij biznesi. Shënimet e tua mbeten aty. Llogaria jote mbetet: mund të krijosh biznesin tënd ose të bashkohesh me një tjetër.",
    "E-Mail (Betrieb)": "E-mail (biznesi)",
    "E-Mail oder Passwort ist falsch.": "E-mail ose fjalëkalim i gabuar.",
    "E-Rechnung": "Faturë elektronike",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Një ofertë nuk është faturë.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Një biznes nuk mund të fshihet me një prekje: faturat duhen ruajtur me ligj për vite (GoBD). Nëse dëshiron ta mbyllësh biznesin ose ta fshish llogarinë, kontakto mbështetjen. Punonjësit mund t'i heqësh te \"Ekipi\".",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Një regjistrim mund të zgjasë më së shumti 24 orë.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Një takim mund të zgjasë më së shumti 31 ditë.",
    "Eine Position hat eine ungültige Menge.": "Një pozicion ka sasi të pavlefshme.",
    "Eine Position hat keine Bezeichnung.": "Një pozicion nuk ka përshkrim.",
    "Einer der Kunden wurde schon zusammengeführt.": "Një nga klientët është bashkuar tashmë.",
