    "Daten werden gesammelt...": "Po mblidhen të dhënat...",
    "Du bekommst eine ZIP-Datei mit Kunden, Aufträgen, Notizen (als Text), allen Rechnungen und Angeboten mit PDF, den Einkaufsbelegen mit Fotos, Terminen und Arbeitszeiten. Das dauert je nach Menge eine Weile und braucht Internet. Bewahre die Datei sicher auf: sie enthält Daten deiner Kunden.": "Merr një skedar ZIP me klientët, punët, shënimet (si tekst), të gjitha faturat dhe ofertat me PDF, faturat e blerjes me foto, takimet dhe orët e punës. Sipas sasisë zgjat pak dhe kërkon internet. Ruaje skedarin me kujdes: përmban të dhënat e klientëve të tu.",
