    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "To tworzy NOWĄ firmę, której jesteś właścicielem. Zaprosił Cię szef? Wtedy wróć i wybierz „Zostałem zaproszony”.",
