    "Datum": "Data",
    "Davon": "W tym",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Szef pokazuje Ci w aplikacji w „Firma → Zespół” kod QR i kod z 8 znaków. Zeskanuj kod QR lub wpisz kod.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Twoje konto i dostęp zostaną usunięte. Tego nie można cofnąć. Notatki nagrane dla firmy zostają tam przy zleceniu (tylko Twoje imię jako tekst).",
