    "Der Server ist gerade nicht erreichbar.": "Serwer jest teraz niedostępny.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Pamięć Twojego pakietu jest pełna. Do nowych nagrań i paragonów potrzebny jest większy pakiet.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Pamięć jest prawie pełna. Do większej pamięci potrzebny jest większy pakiet.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Pamięć jest pełna: nowe nagrania i paragony są odrzucane. Do większej pamięci potrzebny jest większy pakiet. Faktury można nadal tworzyć.",
