    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Brak zgody na powiadomienia. Zezwól w ustawieniach telefonu dla Zunft.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Aparat jest niedostępny. Zezwól na dostęp w ustawieniach lub wpisz kod ręcznie.",
