    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Osoba instaluje Zunft, rejestruje się własnym e-mailem i skanuje ten kod (lub go wpisuje).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Osoba natychmiast przestaje należeć do firmy. Jej notatki zostają. Miejsce się zwalnia.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Osoba natychmiast traci wszelkie powiązanie z Twoją firmą: brak zleceń, klientów, danych. Jej dotychczasowe notatki zostają przy zleceniach (z jej nazwiskiem). Konto należy do niej: może założyć własną firmę lub dołączyć do innej. Miejsce się zwalnia.",
    "Die Rechnung hat keine Positionen.": "Faktura nie ma pozycji.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Faktura jest już oznaczona jako zapłacona. Najpierw ustal z doradcą podatkowym, jak ją skorygować.",
