    "Erstellt": "Wystawione",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Tworzona jest faktura korygująca z własnym numerem, która anuluje tę fakturę. Sama faktura pozostaje zapisana bez zmian i jest oznaczona jako „Anulowana”.\n\nNotatki zlecenia znów są wolne. Potem możesz ponownie sprawdzić zlecenie, poprawić je i utworzyć nową fakturę.\n\nTego nie można cofnąć.",
    "Es wurde nichts aufgenommen.": "Nic nie nagrano.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "Prawie gotowe: wysłaliśmy Ci e-mail. Potwierdź adres, a potem zaloguj się.",
