    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Brak zleceń. Utwórz pierwsze przez „Nowe zlecenie”, a potem dodawaj do niego notatki głosowe.",
    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "Brak klientów. Utwórz klienta lub nagraj notatkę – nowi klienci są rozpoznawani automatycznie.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Brak notatek. Nagraj notatkę (lub wpisz): czas pracy, materiał, szczególne uwagi. Możesz robić dowolnie dużo notatek, także w kilku dniach.",
    "Noch keine erledigten Aufträge. Abgeschlossene und abgerechnete Aufträge erscheinen hier.": "Brak zakończonych zleceń. Zamknięte i rozliczone zlecenia pojawią się tutaj.",
