    "Dieser Kunde existiert nicht mehr.": "Acest client nu mai există.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Acest client are oferte sau facturi și nu poate fi șters (păstrare legală).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Acest telefon nu a primit o adresă pentru notificări. Încearcă din nou mai târziu.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Acest PDF este citit și salvat ca bon.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Încă nu ți-a fost atribuită nicio lucrare. De îndată ce proprietarul sau biroul îți atribuie una, apare aici.",
    "Donnerstag": "Joi",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Pierzi accesul la toate lucrările și clienții acestei firme. Notele tale rămân acolo. Contul tău rămâne: îți poți fonda propria firmă sau te poți alătura alteia.",
    "E-Mail (Betrieb)": "E-mail (firmă)",
    "E-Mail oder Passwort ist falsch.": "E-mailul sau parola este greșită.",
    "E-Rechnung": "Factură electronică",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "O ofertă nu este o factură.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "O firmă nu poate fi ștearsă cu o atingere: facturile trebuie păstrate prin lege ani de zile (GoBD). Dacă vrei să închizi firma sau să ștergi contul, contactează suportul. Angajații îi poți elimina la „Echipă”.",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "O înregistrare poate dura cel mult 24 de ore.",
    "Ein Termin darf höchstens 31 Tage dauern.": "O programare poate dura cel mult 31 de zile.",
