    "Für die E-Rechnung braucht der Kunde eine vollständige Anschrift (Straße, PLZ, Ort).": "Для электронного счёта клиенту нужен полный адрес (улица, индекс, город).",
    "Für die E-Rechnung fehlt die IBAN des Betriebs (Betrieb → Bearbeiten).": "Для электронного счёта отсутствует IBAN предприятия (Предприятие → Изменить).",
    "Für die E-Rechnung fehlt die Steuernummer oder USt-IdNr. des Betriebs.": "Для электронного счёта отсутствует налоговый номер или номер плательщика НДС предприятия.",
