    "Keine Verbindung. Zum Fertigstellen wird Internet gebraucht, weil die Nummer vom Server vergeben wird. Deine Änderungen bleiben erhalten - bitte später noch einmal versuchen.": "Нет соединения. Для завершения нужен интернет, потому что номер присваивает сервер. Ваши изменения сохранены - попробуйте позже.",
    "Konto erstellen": "Создать аккаунт",
