    "Kunden": "Клиенты",
    "Leer = Einkaufspreis unverändert weitergeben. Mit 10 wird jedes Material aus einem Beleg um 10 % teurer in die Rechnung übernommen. Im Prüfbildschirm kann jeder Preis noch geändert werden.": "Пусто = передать закупочную цену без изменений. При 10 каждый материал из чека будет на 10 % дороже в счёте. Каждую цену ещё можно изменить на экране проверки.",
