    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Заказов пока нет. Создайте первый через «Новый заказ», затем сможете добавлять к нему голосовые заметки.",
    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "Клиентов пока нет. Создайте клиента или наговорите заметку – новые клиенты распознаются автоматически.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Заметок пока нет. Запишите заметку (или напишите): рабочее время, материал, особенности. Можно делать сколько угодно заметок, в том числе в разные дни.",
    "Noch keine erledigten Aufträge. Abgeschlossene und abgerechnete Aufträge erscheinen hier.": "Завершённых заказов пока нет. Закрытые и оплаченные заказы появятся здесь.",
