    "Die Beträge wurden automatisch aus dem Foto gelesen. Maßgeblich ist immer das Foto.": "Суми зчитано з фото автоматично. Вирішальним завжди є фото.",
    "Die Datei konnte nicht geteilt werden.": "Не вдалося поділитися файлом.",
