    "Bitte erneut anmelden": "Будь ласка, увійдіть знову",
    "Bitte gültigen Betrag eingeben": "Будь ласка, введіть коректну суму",
    "Bitte gültigen Prozentsatz eingeben": "Будь ласка, введіть коректний відсоток",
