    "Bitte melde dich erneut an.": "Будь ласка, увійдіть знову.",
    "Bitte mindestens eine Position hinzufügen.": "Будь ласка, додайте принаймні одну позицію.",
    "Bitte mit Fingerabdruck, Gesicht oder PIN entsperren.": "Будь ласка, розблокуйте відбитком пальця, обличчям або PIN-кодом.",
    "Bitte zuerst Steuernummer oder USt-IdNr. unter „Betrieb“ eintragen.": "Будь ласка, спершу введіть податковий номер або номер платника ПДВ у розділі «Підприємство».",
    "Bitte zuerst die Anschrift deines Betriebs unter „Betrieb“ eintragen.": "Будь ласка, спершу введіть адресу вашого підприємства в розділі «Підприємство».",
    "Bitte zuerst die E-Mail-Adresse bestätigen (Link in der E-Mail).": "Будь ласка, спершу підтвердіть адресу ел. пошти (посилання в листі).",
    "Brutto": "Брутто",
    "Büro": "Офіс",
    "Dafür fehlt die Berechtigung.": "Для цього немає дозволу.",
    "Das Datum liegt außerhalb des erlaubten Bereichs.": "Дата поза допустимим діапазоном.",
    "Das Dokument konnte nicht erstellt werden.": "Не вдалося створити документ.",
    "Das Ende muss nach dem Beginn liegen.": "Кінець має бути пізніше за початок.",
    "Das Logo konnte nicht hochgeladen werden. Bitte Internetverbindung prüfen.": "Не вдалося завантажити логотип. Перевірте підключення до інтернету.",
