    "Das Passwort ist zu schwach.": "Пароль занадто слабкий.",
    "Das Team konnte nicht geladen werden.": "Не вдалося завантажити команду.",
    "Das hat leider nicht geklappt. Bitte später erneut versuchen.": "На жаль, не вийшло. Спробуйте пізніше.",
    "Das hat nicht geklappt. Bitte erneut versuchen.": "Не вийшло. Спробуйте ще раз.",
    "Das ist derselbe Kunde.": "Це той самий клієнт.",
    "Das ist für den Inhaber eines Betriebs nicht möglich.": "Це неможливо для власника підприємства.",
    "Das ist kein Einladungscode von Zunft.": "Це не код запрошення Zunft.",
    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Це створює НОВЕ підприємство, яким ви володієте. Вас запросив керівник? Тоді поверніться й виберіть «Мене запросили».",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "Це було неможливо (більше не призначено?).",
    "Datum": "Дата",
    "Davon": "З них",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Ваш керівник показує вам у застосунку в розділі «Підприємство → Команда» QR-код і код із 8 символів. Відскануйте QR-код або введіть код.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Ваш обліковий запис і доступ буде видалено. Це не можна скасувати. Нотатки, які ви записали для підприємства, залишаються там біля замовлення (лише ваше ім'я як текст).",
    "Deine erfasste Arbeitszeit": "Ваш записаний робочий час",
    "Der Anruf konnte nicht gestartet werden.": "Не вдалося розпочати дзвінок.",
    "Der Auftrag dieser Notiz existiert nicht mehr.": "Замовлення цієї нотатки більше не існує.",
    "Der Auftrag existiert nicht mehr": "Замовлення більше не існує",
    "Der Beleg konnte nicht gespeichert werden.": "Не вдалося зберегти чек.",
    "Der Code besteht aus 8 Zeichen (Buchstaben und Ziffern).": "Код складається з 8 символів (літери й цифри).",
    "Der Code ist ungültig, abgelaufen oder schon benutzt. Bitte beim Chef einen neuen Code holen.": "Код недійсний, прострочений або вже використаний. Отримайте в керівника новий код.",
    "Der Code {0} funktioniert danach nicht mehr.": "Код {0} після цього перестане працювати.",
    "Der Export ist fehlgeschlagen. Bitte Internetverbindung prüfen und erneut versuchen.": "Експорт не вдався. Перевірте підключення до інтернету й спробуйте знову.",
    "Der Kunde existiert nicht mehr": "Клієнта більше не існує",
    "Der Kunde existiert nicht mehr.": "Клієнта більше не існує.",
    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "Сервер відхилив запит. Спробуйте пізніше.",
    "Der Server ist gerade nicht erreichbar.": "Сервер зараз недоступний.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Сховище вашого тарифу заповнене. Для нових записів і чеків потрібен більший тариф.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Сховище майже заповнене. Для більшого обсягу потрібен більший тариф.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Сховище заповнене: нові записи та чеки відхиляються. Для більшого обсягу потрібен більший тариф. Рахунки можна й надалі створювати.",
    "Der Status konnte nicht geändert werden.": "Не вдалося змінити статус.",
    "Der Upload wurde abgelehnt.": "Завантаження відхилено.",
    "Der laufende Timer für „{0}“ wurde beendet ({1} Std).": "Запущений таймер для «{0}» зупинено ({1} год).",
    "Deutsche IBAN hat 22 Zeichen": "Німецький IBAN має 22 символи",
    "Dezember": "Грудень",
    "Die Aufnahme konnte nicht abgespielt werden.": "Не вдалося відтворити запис.",
    "Die Aufnahme konnte nicht geladen werden. Bitte Internetverbindung prüfen.": "Не вдалося завантажити запис. Перевірте підключення до інтернету.",
    "Die Aufnahme konnte nicht gespeichert werden.": "Не вдалося зберегти запис.",
    "Die Aufnahme konnte nicht gestartet werden.": "Не вдалося почати запис.",
    "Die Aufnahme war zu kurz.": "Запис був надто коротким.",
    "Die Belege konnten nicht geladen werden.": "Не вдалося завантажити чеки.",
    "Die Bestätigung hat nicht geklappt. Die App-Sperre bleibt aus.": "Підтвердження не спрацювало. Блокування застосунку залишається вимкненим.",
    "Die Betriebsdaten werden noch geladen.": "Дані підприємства ще завантажуються.",
    "Die Datei ist zu groß.": "Файл завеликий.",
    "Die Datei wurde abgelehnt.": "Файл відхилено.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Немає дозволу на сповіщення. Дозвольте в налаштуваннях телефону для Zunft.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Камера недоступна. Дозвольте доступ у налаштуваннях або введіть код вручну.",
    "Die Karte konnte nicht geöffnet werden.": "Не вдалося відкрити карту.",
    "Die Notiz ist zu lang (höchstens {0} Zeichen).": "Нотатка задовга (не більше {0} символів).",
    "Die Notiz kann nicht mehr entfernt werden (bereits abgerechnet?).": "Нотатку більше не можна видалити (вже оплачена?).",
    "Die Notiz konnte nicht gespeichert werden.": "Не вдалося зберегти нотатку.",
    "Die Notiz konnte nicht verarbeitet werden.": "Не вдалося обробити нотатку.",
    "Die Notizen konnten nicht geladen werden.": "Не вдалося завантажити нотатки.",
    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "Не вдалося завантажити нотатки. Перевірте підключення до інтернету.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "Перерва має бути коротшою за робочий час.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "Людина знову отримує доступ (і займає місце).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Людина встановлює Zunft, реєструється зі своєю ел. поштою та сканує цей код (або вводить його).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Людина одразу виходить із підприємства. Її нотатки зберігаються. Місце звільняється.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Людина одразу втрачає будь-який зв'язок із вашим підприємством: жодних замовлень, клієнтів, даних. Її попередні нотатки залишаються біля замовлень (з її ім'ям). Обліковий запис належить їй: вона може створити своє підприємство або приєднатися до іншого. Місце звільняється.",
    "Die Rechnung hat keine Positionen.": "У рахунку немає позицій.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Рахунок уже позначено як оплачений. Спершу з'ясуйте з податковим консультантом, як його виправити.",
    "Die Rechnung konnte nicht storniert werden.": "Не вдалося сторнувати рахунок.",
    "Die Verarbeitung ist fehlgeschlagen.": "Обробка не вдалася.",
    "Dienstag": "Вівторок",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Ця нотатка не належить жодному замовленню. Відхиліть її й запишіть знову.",
    "Diese Rechnung wurde schon storniert.": "Цей рахунок уже сторновано.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Цей час уже оплачено й його не можна видалити.",
    "Diesen Kunden gibt es schon": "Такий клієнт уже є",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Це замовлення оплачено. Нотатки більше не можна записувати.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Це замовлення закрите. Нотатки більше не можна записувати.",
    "Dieser Kunde existiert nicht mehr.": "Цього клієнта більше не існує.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "У цього клієнта є пропозиції або рахунки, його не можна видалити (обов'язкове зберігання).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Цей телефон не отримав адресу для сповіщень. Спробуйте пізніше.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Цей PDF буде прочитано й збережено як чек.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Вам ще не призначено жодного замовлення. Щойно власник або офіс призначить замовлення, воно з'явиться тут.",
    "Donnerstag": "Четвер",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Ви втратите доступ до всіх замовлень і клієнтів цього підприємства. Ваші нотатки там залишаться. Ваш обліковий запис залишиться: ви можете створити своє підприємство або приєднатися до іншого.",
    "E-Mail (Betrieb)": "Ел. пошта (підприємство)",
    "E-Mail oder Passwort ist falsch.": "Неправильна ел. пошта або пароль.",
    "E-Rechnung": "Електронний рахунок",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Пропозиція - не рахунок.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Підприємство не можна видалити одним дотиком: рахунки за законом мають зберігатися роками (GoBD). Якщо ви хочете закрити підприємство або видалити обліковий запис, зверніться до підтримки. Працівників можна видалити в розділі «Команда».",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Запис може тривати не більше 24 годин.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Зустріч може тривати не більше 31 дня.",
    "Eine Position hat eine ungültige Menge.": "У позиції недопустима кількість.",
    "Eine Position hat keine Bezeichnung.": "У позиції немає найменування.",
    "Einer der Kunden wurde schon zusammengeführt.": "Одного з клієнтів уже об'єднано.",
    "Einige Änderungen wurden abgelehnt": "Деякі зміни було відхилено",
    "Einladung zurückziehen?": "Відкликати запрошення?",
    "Einladung: {0}": "Запрошення: {0}",
    "Einmal benutzbar, gültig bis {0}": "Одноразовий, дійсний до {0}",
    "Einschalten": "Увімкнути",
    "Ende": "Кінець",
    "Entwurf": "Чернетка",
    "Erfasst von": "Записав(ла)",
    "Erfasste Zeit abrechnen": "Оплатити записаний час",
    "Erledigt": "Виконано",
    "Erledigt ({0})": "Виконано ({0})",
    "Erstellt": "Виставлено",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Створюється сторно-рахунок із власним номером, який анулює цей рахунок. Сам рахунок залишається збереженим без змін і позначається «Сторновано».\n\nНотатки замовлення знову звільняються. Після цього ви можете знову перевірити замовлення, виправити його й створити новий рахунок.\n\nЦе не можна скасувати.",
    "Es wurde nichts aufgenommen.": "Нічого не записано.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "Майже готово: ми надіслали вам листа. Підтвердьте адресу й потім увійдіть.",
    "Februar": "Лютий",
    "Firma": "Фірма",
    "Format: DE und 9 Ziffern": "Формат: DE і 9 цифр",
    "Frau": "Пані",
    "Freitag": "П'ятниця",
    "Für Rechnungen fehlt noch: {0}": "Для рахунків ще бракує: {0}",
    "Für den Auftrag „{0}“. {1}": "Для замовлення «{0}». {1}",
    "Für die E-Rechnung braucht der Kunde eine vollständige Anschrift (Straße, PLZ, Ort).": "Для електронного рахунку клієнту потрібна повна адреса (вулиця, індекс, місто).",
    "Für die E-Rechnung fehlt die IBAN des Betriebs (Betrieb → Bearbeiten).": "Для електронного рахунку бракує IBAN підприємства (Підприємство → Змінити).",
    "Für die E-Rechnung fehlt die Steuernummer oder USt-IdNr. des Betriebs.": "Для електронного рахунку бракує податкового номера або номера платника ПДВ підприємства.",
    "Für die E-Rechnung fehlt die vollständige Anschrift des Betriebs.": "Для електронного рахунку бракує повної адреси підприємства.",
    "Für diesen Auftrag ist Zeit erfasst: {0} Std ({1}).": "Для цього замовлення записано час: {0} год ({1}).",
    "Für dieses Konto existiert bereits ein Betrieb.": "Для цього облікового запису вже існує підприємство.",
