    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Ovo izrađuje NOVI obrt kojemu si vlasnik. Je li te pozvao šef? Tada se vrati i odaberi „Pozvan sam”.",
