    "Datum": "Datum",
    "Davon": "Od toga",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Šef ti u aplikaciji pod „Obrt → Tim” pokazuje QR kod i kod od 8 znakova. Skeniraj QR kod ili utipkaj kod.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Tvoj račun i pristup bit će izbrisani. To se ne može poništiti. Bilješke koje si snimio za obrt ostaju ondje uz nalog (samo tvoje ime kao tekst).",
