    "Der Kunde existiert nicht mehr": "Klijent više ne postoji",
    "Der Kunde existiert nicht mehr.": "Klijent više ne postoji.",
    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "Poslužitelj je odbio zahtjev. Pokušaj ponovno kasnije.",
    "Der Server ist gerade nicht erreichbar.": "Poslužitelj trenutno nije dostupan.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Pohrana tvog paketa je puna. Za nove snimke i račune potreban je veći paket.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Pohrana je gotovo puna. Za više pohrane potreban je veći paket.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Pohrana je puna: nove snimke i računi se odbijaju. Za više pohrane potreban je veći paket. Računi se i dalje mogu izrađivati.",
