    "Diese Rechnung wurde schon storniert.": "Ovaj račun je već storniran.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Ovo vrijeme je već naplaćeno i ne može se izbrisati.",
    "Diesen Kunden gibt es schon": "Ovaj klijent već postoji",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Ovaj nalog je naplaćen. Više se ne mogu snimati bilješke.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Ovaj nalog je zatvoren. Više se ne mogu snimati bilješke.",
    "Dieser Kunde existiert nicht mehr.": "Ovaj klijent više ne postoji.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Ovaj klijent ima ponude ili račune i ne može se izbrisati (zakonsko čuvanje).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Ovaj telefon nije dobio adresu za obavijesti. Pokušaj ponovno kasnije.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Ovaj PDF se čita i sprema kao račun.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Još ti nije dodijeljen nijedan nalog. Čim ti vlasnik ili ured dodijeli nalog, pojavit će se ovdje.",
    "Donnerstag": "Četvrtak",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Gubiš pristup svim nalozima i klijentima ovog obrta. Tvoje bilješke ondje ostaju. Tvoj račun ostaje: možeš osnovati vlastiti obrt ili se pridružiti drugom.",
    "E-Mail (Betrieb)": "E-pošta (obrt)",
    "E-Mail oder Passwort ist falsch.": "E-pošta ili lozinka nisu ispravni.",
    "E-Rechnung": "E-račun",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Ponuda nije račun.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Obrt se ne može izbrisati jednim dodirom: računi se po zakonu moraju čuvati godinama (GoBD). Ako želiš zatvoriti obrt ili izbrisati račun, obrati se podršci. Zaposlenike možeš ukloniti pod „Tim”.",
