    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Izrađuje se storno račun s vlastitim brojem koji poništava ovaj račun. Sam račun ostaje spremljen nepromijenjen i označava se „Storniran”.\n\nBilješke naloga ponovno se oslobađaju. Nakon toga možeš ponovno provjeriti nalog, ispraviti ga i izraditi novi račun.\n\nTo se ne može poništiti.",
