    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Još nema naloga. Izradi prvi s „Novi nalog”, zatim mu možeš dodavati glasovne bilješke.",
