    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Još nema bilješki. Snimi bilješku (ili je upiši): radno vrijeme, materijal, posebnosti. Možeš napraviti koliko god bilješki želiš, i kroz više dana.",
