    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Nedostaje dopuštenje za obavijesti. Molimo dopusti ga za Zunft u postavkama telefona.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Kamera nije dostupna. Dopusti pristup u postavkama ili utipkaj kod ručno.",
