    "Die Pause muss kürzer sein als die Arbeitszeit.": "Stanka mora biti kraća od radnog vremena.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "Osoba ponovo dobiva pristup (i zauzima mesto).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Osoba instalira Zunft, registrira se vlastitom e-poštam i skenira ovaj kod (ili ga utipka).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Osoba odmah izlazi iz radnje. Njezine bilješke ostaju. Mesto se oslobađa.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Osoba odmah gubi svaku vezu s tvojim radnjom: nema naloga, klijenata ni podataka. Njezine dosadašnje bilješke ostaju uz naloge (s njezinim imenom). Račun pripada njoj: može osnovati vlastiti radnja ili se pridružiti drugom. Mesto se oslobađa.",
    "Die Rechnung hat keine Positionen.": "Račun nema stavki.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Račun je već označen kao plaćen. Najprije s poreznim savjetnikom razjasni kako ga ispraviti.",
