    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Ovaj nalog je zatvoren. Više se ne mogu snimati bilješke.",
    "Dieser Kunde existiert nicht mehr.": "Ovaj klijent više ne postoji.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Ovaj klijent ima ponude ili račune i ne može se izbrisati (zakonsko čuvanje).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Ovaj telefon nije dobio adresu za obavijesti. Pokušaj ponovo kasnije.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Ovaj PDF se čita i sprema kao račun.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Još ti nije dodeljen nijedan nalog. Čim ti vlasnik ili kancelarija dodeli nalog, pojavit će se ovdje.",
    "Donnerstag": "Četvrtak",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Gubiš pristup svim nalozima i klijentima ovog radnje. Tvoje bilješke ondje ostaju. Tvoj račun ostaje: možeš osnovati vlastiti radnja ili se pridružiti drugom.",
    "E-Mail (Betrieb)": "E-pošta (radnja)",
    "E-Mail oder Passwort ist falsch.": "E-pošta ili lozinka nisu ispravni.",
    "E-Rechnung": "E-račun",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Ponuda nije račun.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Radnja se ne može izbrisati jednim dodirom: računi se po zakonu moraju čuvati godinama (GoBD). Ako želiš zatvoriti radnja ili izbrisati račun, obrati se podršci. Zaposlenike možeš ukloniti pod „Tim”.",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Unos smije trajati najviše 24 sata.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Termin smije trajati najviše 31 dan.",
