    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Još nema naloga. Izradi prvi s „Novi nalog”, zatim mu možeš dodavati glasovne bilješke.",
    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "Još nema klijenata. Izradi klijenta ili izgovori bilješku – novi klijenti prepoznaju se automatski.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Još nema bilješki. Snimi bilješku (ili je upiši): radno vreme, materijal, posebnosti. Možeš napraviti koliko god bilješki želiš, i kroz više dana.",
