    "Das ist kein Einladungscode von Zunft.": "Това не е код за покана от Zunft.",
    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "Това създава НОВА фирма, на която си собственик. Поканил ли те е шефът ти? Тогава се върни и избери „Поканен съм“.",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "Това не беше възможно (вече не е възложено?).",
    "Datum": "Дата",
    "Davon": "От тях",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "Шефът ти показва в приложението под „Фирма → Екип“ QR код и код от 8 знака. Сканирай QR кода или въведи кода.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "Акаунтът и достъпът ти ще бъдат изтрити. Това не може да се отмени. Бележките, които си записал за фирма, остават там към поръчката (само името ти като текст).",
