    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "Хранилището на пакета ти е пълно. За нови записи и бележки е нужен по-голям пакет.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "Хранилището е почти пълно. За повече място е нужен по-голям пакет.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "Хранилището е пълно: новите записи и бележки се отхвърлят. За повече място е нужен по-голям пакет. Фактури все още могат да се създават.",
