    "Dezember": "Декември",
    "Die Aufnahme konnte nicht abgespielt werden.": "Записът не можа да се възпроизведе.",
    "Die Aufnahme konnte nicht geladen werden. Bitte Internetverbindung prüfen.": "Записът не можа да се зареди. Провери интернет връзката.",
    "Die Aufnahme konnte nicht gespeichert werden.": "Записът не можа да се запази.",
    "Die Aufnahme konnte nicht gestartet werden.": "Записът не можа да започне.",
    "Die Aufnahme war zu kurz.": "Записът беше твърде кратък.",
    "Die Belege konnten nicht geladen werden.": "Бележките не можаха да се заредят.",
    "Die Bestätigung hat nicht geklappt. Die App-Sperre bleibt aus.": "Потвърждението не проработи. Заключването на приложението остава изключено.",
    "Die Betriebsdaten werden noch geladen.": "Данните на фирмата още се зареждат.",
    "Die Datei ist zu groß.": "Файлът е твърде голям.",
    "Die Datei wurde abgelehnt.": "Файлът беше отхвърлен.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "Липсва разрешение за известия. Моля, разреши го за Zunft в настройките на телефона.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "Камерата не е налична. Разреши достъпа в настройките или въведи кода ръчно.",
    "Die Karte konnte nicht geöffnet werden.": "Картата не можа да се отвори.",
    "Die Notiz ist zu lang (höchstens {0} Zeichen).": "Бележката е твърде дълга (най-много {0} знака).",
    "Die Notiz kann nicht mehr entfernt werden (bereits abgerechnet?).": "Бележката вече не може да се премахне (вече фактурирана?).",
    "Die Notiz konnte nicht gespeichert werden.": "Бележката не можа да се запази.",
    "Die Notiz konnte nicht verarbeitet werden.": "Бележката не можа да се обработи.",
    "Die Notizen konnten nicht geladen werden.": "Бележките не можаха да се заредят.",
    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "Бележките не можаха да се заредят. Провери интернет връзката.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "Почивката трябва да е по-кратка от работното време.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "Човекът отново получава достъп (и заема място).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "Човекът инсталира Zunft, регистрира се със собствен имейл и сканира този код (или го въвежда).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "Човекът веднага напуска фирмата. Бележките му остават. Мястото се освобождава.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "Човекът веднага губи всякаква връзка с твоята фирма: няма поръчки, клиенти, данни. Досегашните му бележки остават при поръчките (с неговото име). Акаунтът е негов: може да създаде собствена фирма или да се присъедини към друга. Мястото се освобождава.",
    "Die Rechnung hat keine Positionen.": "Фактурата няма позиции.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "Фактурата вече е отбелязана като платена. Първо изясни с данъчния консултант как да се коригира.",
    "Die Rechnung konnte nicht storniert werden.": "Фактурата не можа да се сторнира.",
    "Die Verarbeitung ist fehlgeschlagen.": "Обработката не успя.",
    "Dienstag": "Вторник",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "Тази бележка не принадлежи към никоя поръчка. Отхвърли я и запиши отново.",
    "Diese Rechnung wurde schon storniert.": "Тази фактура вече е сторнирана.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "Това време вече е фактурирано и не може да се изтрие.",
    "Diesen Kunden gibt es schon": "Този клиент вече съществува",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "Тази поръчка е фактурирана. Вече не могат да се записват бележки.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "Тази поръчка е затворена. Вече не могат да се записват бележки.",
    "Dieser Kunde existiert nicht mehr.": "Този клиент вече не съществува.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "Този клиент има оферти или фактури и не може да се изтрие (законово съхранение).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "Този телефон не получи адрес за известия. Опитай отново по-късно.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "Този PDF се чете и запазва като бележка.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "Още не ти е възложена поръчка. Щом собственикът или офисът ти възложи поръчка, тя ще се появи тук.",
    "Donnerstag": "Четвъртък",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "Губиш достъпа до всички поръчки и клиенти на тази фирма. Бележките ти остават там. Акаунтът ти остава: можеш да създадеш собствена фирма или да се присъединиш към друга.",
    "E-Mail (Betrieb)": "Имейл (фирма)",
    "E-Mail oder Passwort ist falsch.": "Имейлът или паролата са грешни.",
    "E-Rechnung": "Е-фактура",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "Офертата не е фактура.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "Фирма не може да се изтрие с едно докосване: фактурите по закон трябва да се пазят с години (GoBD). Ако искаш да закриеш фирмата или да изтриеш акаунта, свържи се с поддръжката. Служители можеш да премахнеш под „Екип“.",
    "Ein Eintrag darf höchstens 24 Stunden dauern.": "Един запис може да трае най-много 24 часа.",
    "Ein Termin darf höchstens 31 Tage dauern.": "Една среща може да трае най-много 31 дни.",
    "Eine Position hat eine ungültige Menge.": "Една позиция има невалидно количество.",
    "Eine Position hat keine Bezeichnung.": "Една позиция няма наименование.",
    "Einer der Kunden wurde schon zusammengeführt.": "Един от клиентите вече е обединен.",
    "Einige Änderungen wurden abgelehnt": "Някои промени бяха отхвърлени",
    "Einladung zurückziehen?": "Да се оттегли ли поканата?",
    "Einladung: {0}": "Покана: {0}",
    "Einmal benutzbar, gültig bis {0}": "За еднократна употреба, валидна до {0}",
    "Einschalten": "Включи",
    "Ende": "Край",
    "Entwurf": "Чернова",
    "Erfasst von": "Записано от",
    "Erfasste Zeit abrechnen": "Фактурирай записаното време",
    "Erledigt": "Изпълнено",
    "Erledigt ({0})": "Изпълнено ({0})",
    "Erstellt": "Издадена",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "Създава се кредитно известие със собствен номер, което анулира тази фактура. Самата фактура остава запазена непроменена и се отбелязва „Сторнирана“.\n\nБележките на поръчката отново се освобождават. След това можеш да прегледаш поръчката отново, да я коригираш и да създадеш нова фактура.\n\nТова не може да се отмени.",
    "Es wurde nichts aufgenommen.": "Нищо не е записано.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "Почти готово: изпратихме ти имейл. Потвърди адреса и после влез.",
    "Februar": "Февруари",
    "Firma": "Фирма",
    "Format: DE und 9 Ziffern": "Формат: DE и 9 цифри",
