    "Für den Auftrag „{0}“. {1}": "За поръчката „{0}“. {1}",
    "Für die E-Rechnung braucht der Kunde eine vollständige Anschrift (Straße, PLZ, Ort).": "За е-фактурата клиентът има нужда от пълен адрес (улица, пощенски код, град).",
    "Für die E-Rechnung fehlt die IBAN des Betriebs (Betrieb → Bearbeiten).": "За е-фактурата липсва IBAN на фирмата (Фирма → Редактирай).",
    "Für die E-Rechnung fehlt die Steuernummer oder USt-IdNr. des Betriebs.": "За е-фактурата липсва данъчният номер или ДДС номерът на фирмата.",
    "Für die E-Rechnung fehlt die vollständige Anschrift des Betriebs.": "За е-фактурата липсва пълният адрес на фирмата.",
    "Für diesen Auftrag ist Zeit erfasst: {0} Std ({1}).": "За тази поръчка е записано време: {0} ч ({1}).",
    "Für dieses Konto existiert bereits ein Betrieb.": "За този акаунт вече има фирма.",
    "Für eine Rechnung fehlt noch in den Betriebsdaten: {0}.": "За фактура в данните на фирмата още липсва: {0}.",
    "Für eine Vorschau gibt es keine E-Rechnung.": "За прегледа няма е-фактура.",
