    "Ich wurde eingeladen": "Поканен съм",
    "Im Paket des Betriebs ist kein Platz mehr frei. Bitte den Chef fragen.": "В пакета на фирмата няма свободно място. Попитай шефа си.",
    "In Angebot umwandeln": "Преобразувай в оферта",
