    "In Rechnung umwandeln": "Преобразувай във фактура",
    "In den Notizen steht außerdem Arbeitszeit: {0} Std. Sonst würde sie doppelt berechnet.": "В бележките има и работно време: {0} ч. Иначе би се фактурирало два пъти.",
    "In der Notiz genannt: \"{0}\" - übernehmen?": "Споменато в бележката: „{0}“ - да се приложи ли?",
    "In diesem Monat ist keine Zeit erfasst.": "През този месец не е записано време.",
    "In dieser Woche ist keine Zeit erfasst.": "През тази седмица не е записано време.",
    "Inhaber": "Собственик",
    "Ist alles scharf und vollständig zu lesen, auch die Summe? Sonst lieber neu aufnehmen.": "Всичко ли е ясно и напълно четливо, включително сумата? Иначе по-добре запиши отново.",
    "Ja (ZUGFeRD, EN 16931)": "Да (ZUGFeRD, EN 16931)",
