    "Juni": "Юни",
    "Kein Kunde im Auftrag": "Няма клиент в поръчката",
    "Kein Kunde zugeordnet": "Не е зададен клиент",
    "Keine Termine an diesem Tag.": "Няма срещи в този ден.",
    "Keine Verbindung.": "Няма връзка.",
    "Keine Verbindung. Bitte Internet prüfen und erneut versuchen.": "Няма връзка. Провери интернет и опитай отново.",
    "Keine Verbindung. Bitte später erneut versuchen.": "Няма връзка. Опитай отново по-късно.",
    "Keine Verbindung. Bitte später noch einmal versuchen.": "Няма връзка. Опитай отново по-късно.",
    "Keine Verbindung. Der Status kann nur online geändert werden.": "Няма връзка. Статусът може да се променя само онлайн.",
    "Keine Verbindung. Zum Abhaken wird Internet gebraucht.": "Няма връзка. Отбелязването изисква интернет.",
    "Keine Verbindung. Zum Einschalten wird Internet gebraucht.": "Няма връзка. Включването изисква интернет.",
    "Keine Verbindung. Zum Fertigstellen wird Internet gebraucht, weil die Nummer vom Server vergeben wird. Deine Änderungen bleiben erhalten - bitte später noch einmal versuchen.": "Няма връзка. Завършването изисква интернет, защото номерът се присвоява от сървъра. Промените ти се запазват - опитай отново по-късно.",
    "Konto erstellen": "Създай акаунт",
    "Kunde bearbeiten": "Редактирай клиента",
    "Kunden": "Клиенти",
    "Leer = Einkaufspreis unverändert weitergeben. Mit 10 wird jedes Material aus einem Beleg um 10 % teurer in die Rechnung übernommen. Im Prüfbildschirm kann jeder Preis noch geändert werden.": "Празно = прехвърли покупната цена непроменена. При 10 всеки материал от бележка става с 10 % по-скъп във фактурата. Всяка цена може още да се промени на екрана за проверка.",
    "Leistungszeitraum": "Период на услугата",
