    "Mein Chef hat mir einen Code oder QR-Code gegeben.": "Шефът ми даде код или QR код.",
    "Meine Zeiten": "Моето време",
    "Meister": "Майстор",
    "Meister und Gesellen können eigene Kunden und Aufträge erstellen. Inhaber und Büro dürfen das immer.": "Майсторите и калфите могат да създават собствени клиенти и поръчки. Собственикът и офисът винаги могат.",
    "Mindestens eine Position ist ungültig (Menge, Preis oder Bezeichnung).": "Поне една позиция е невалидна (количество, цена или наименование).",
