    "Niemand - nur Inhaber und Büro sehen den Auftrag": "Никой - поръчката се вижда само от собственика и офиса",
    "Noch kein Konto? Registrieren": "Нямаш акаунт? Регистрирай се",
    "Noch kein Kunde": "Още няма клиент",
    "Noch keine Aufträge. Lege mit „Neuer Auftrag“ den ersten an, dann kannst du ihm Sprachnotizen hinzufügen.": "Още няма поръчки. Създай първата с „Нова поръчка“, после можеш да добавяш гласови бележки към нея.",
    "Noch keine Kunden. Lege einen Kunden an oder sprich eine Notiz ein – neue Kunden werden automatisch erkannt.": "Още няма клиенти. Създай клиент или кажи бележка – новите клиенти се разпознават автоматично.",
    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "Още няма бележки. Запиши бележка (или я напиши): работно време, материал, особености. Можеш да правиш колкото искаш бележки, и в няколко дни.",
    "Noch keine erledigten Aufträge. Abgeschlossene und abgerechnete Aufträge erscheinen hier.": "Още няма завършени поръчки. Затворените и фактурирани поръчки се появяват тук.",
