    "Alle Aufträge wandern zum bleibenden Kunden. Fehlende Angaben werden ergänzt, abweichende Angaben stehen danach in den Notizen. Bereits erstellte Angebote und Rechnungen bleiben unverändert (sie müssen laut Gesetz so aufbewahrt werden).": "همه سفارش‌ها به مشتریِ باقی‌مانده منتقل می‌شوند. اطلاعات ناقص تکمیل می‌شود و اطلاعات متفاوت سپس در یادداشت‌ها می‌آید. پیشنهادها و فاکتورهای صادرشده بدون تغییر می‌مانند (قانون می‌خواهد همین‌طور نگهداری شوند).",
