    "Bitte einen Betrag zwischen 0 und 1.000 Euro eintragen, zum Beispiel 75,00.": "لطفاً مبلغی بین ۰ و ۱٬۰۰۰ یورو وارد کنید، مثلاً ۷۵٫۰۰.",
    "Bitte einen gültigen Preis eingeben (z.B. 68,50).": "لطفاً قیمت معتبر وارد کنید (مثلاً ۶۸٫۵۰).",
