    "Bitte mit Fingerabdruck, Gesicht oder PIN entsperren.": "لطفاً با اثر انگشت، چهره یا PIN قفل را باز کنید.",
    "Bitte zuerst Steuernummer oder USt-IdNr. unter „Betrieb“ eintragen.": "لطفاً ابتدا شماره مالیاتی یا شناسه مالیات بر ارزش افزوده را زیر «کسب‌وکار» وارد کنید.",
    "Bitte zuerst die Anschrift deines Betriebs unter „Betrieb“ eintragen.": "لطفاً ابتدا نشانی کسب‌وکارتان را زیر «کسب‌وکار» وارد کنید.",
    "Bitte zuerst die E-Mail-Adresse bestätigen (Link in der E-Mail).": "لطفاً ابتدا نشانی ایمیل را تأیید کنید (پیوند در ایمیل).",
