    "Das hat leider nicht geklappt. Bitte später erneut versuchen.": "متأسفانه نشد. لطفاً بعداً دوباره تلاش کنید.",
    "Das hat nicht geklappt. Bitte erneut versuchen.": "نشد. لطفاً دوباره تلاش کنید.",
    "Das ist derselbe Kunde.": "این همان مشتری است.",
    "Das ist für den Inhaber eines Betriebs nicht möglich.": "این برای مالک یک کسب‌وکار ممکن نیست.",
    "Das ist kein Einladungscode von Zunft.": "این کد دعوت‌نامه Zunft نیست.",
    "Das legt einen NEUEN Betrieb an, dem du als Inhaber gehörst. Wurdest du von deinem Chef eingeladen? Dann geh zurück und wähle „Ich wurde eingeladen“.": "این یک کسب‌وکار جدید ایجاد می‌کند که مالک آن هستید. رئیستان دعوتتان کرده؟ پس برگردید و «دعوت شده‌ام» را انتخاب کنید.",
    "Das war nicht möglich (nicht mehr zugewiesen?).": "این ممکن نبود (دیگر اختصاص ندارد؟).",
    "Datum": "تاریخ",
    "Davon": "از آن میان",
    "Dein Chef zeigt dir in der App unter „Betrieb → Team“ einen QR-Code und einen Code mit 8 Zeichen. Scanne den QR-Code oder tippe den Code ein.": "رئیس شما در برنامه زیر «کسب‌وکار ← تیم» یک کد QR و یک کد ۸ نویسه‌ای نشان می‌دهد. کد QR را اسکن کنید یا کد را تایپ کنید.",
    "Dein Konto und dein Zugang werden gelöscht. Das kann nicht rückgängig gemacht werden. Notizen, die du für einen Betrieb aufgenommen hast, bleiben dort beim Auftrag (nur dein Name als Text).": "حساب و دسترسی شما حذف می‌شود. این کار قابل بازگشت نیست. یادداشت‌هایی که برای یک کسب‌وکار ضبط کرده‌اید آنجا کنار سفارش کار می‌مانند (فقط نام شما به صورت متن).",
    "Deine erfasste Arbeitszeit": "زمان کار ثبت‌شده شما",
    "Der Anruf konnte nicht gestartet werden.": "تماس شروع نشد.",
    "Der Auftrag dieser Notiz existiert nicht mehr.": "سفارش کار این یادداشت دیگر وجود ندارد.",
    "Der Auftrag existiert nicht mehr": "سفارش کار دیگر وجود ندارد",
    "Der Beleg konnte nicht gespeichert werden.": "رسید ذخیره نشد.",
    "Der Code besteht aus 8 Zeichen (Buchstaben und Ziffern).": "کد از ۸ نویسه (حرف و رقم) تشکیل شده است.",
    "Der Code ist ungültig, abgelaufen oder schon benutzt. Bitte beim Chef einen neuen Code holen.": "کد نامعتبر، منقضی یا قبلاً استفاده شده است. از رئیستان کد جدید بگیرید.",
    "Der Code {0} funktioniert danach nicht mehr.": "کد {0} پس از آن دیگر کار نمی‌کند.",
    "Der Export ist fehlgeschlagen. Bitte Internetverbindung prüfen und erneut versuchen.": "خروجی ناموفق بود. لطفاً اتصال اینترنت را بررسی کنید و دوباره تلاش کنید.",
    "Der Kunde existiert nicht mehr": "مشتری دیگر وجود ندارد",
    "Der Kunde existiert nicht mehr.": "مشتری دیگر وجود ندارد.",
    "Der Server hat die Anfrage abgelehnt. Bitte später erneut versuchen.": "سرور درخواست را رد کرد. لطفاً بعداً دوباره تلاش کنید.",
    "Der Server ist gerade nicht erreichbar.": "سرور اکنون در دسترس نیست.",
    "Der Speicher deines Pakets ist voll. Für neue Aufnahmen und Belege wird ein größeres Paket gebraucht.": "فضای ذخیره‌سازی بسته شما پر است. برای ضبط‌ها و رسیدهای جدید به بسته بزرگ‌تر نیاز است.",
    "Der Speicher ist fast voll. Für mehr Speicher wird ein größeres Paket gebraucht.": "فضای ذخیره‌سازی تقریباً پر است. برای فضای بیشتر به بسته بزرگ‌تر نیاز است.",
    "Der Speicher ist voll: neue Aufnahmen und Belege werden abgelehnt. Für mehr Speicher wird ein größeres Paket gebraucht. Rechnungen können weiter erstellt werden.": "فضای ذخیره‌سازی پر است: ضبط‌ها و رسیدهای جدید رد می‌شوند. برای فضای بیشتر به بسته بزرگ‌تر نیاز است. فاکتورها همچنان قابل ایجاد هستند.",
    "Der Status konnte nicht geändert werden.": "وضعیت تغییر نکرد.",
    "Der Upload wurde abgelehnt.": "بارگذاری رد شد.",
    "Der laufende Timer für „{0}“ wurde beendet ({1} Std).": "زمان‌سنج در حال اجرای «{0}» متوقف شد ({1} ساعت).",
    "Deutsche IBAN hat 22 Zeichen": "IBAN آلمانی ۲۲ نویسه دارد",
    "Dezember": "دسامبر",
    "Die Aufnahme konnte nicht abgespielt werden.": "ضبط پخش نشد.",
    "Die Aufnahme konnte nicht geladen werden. Bitte Internetverbindung prüfen.": "ضبط بارگذاری نشد. لطفاً اتصال اینترنت را بررسی کنید.",
    "Die Aufnahme konnte nicht gespeichert werden.": "ضبط ذخیره نشد.",
    "Die Aufnahme konnte nicht gestartet werden.": "ضبط شروع نشد.",
    "Die Aufnahme war zu kurz.": "ضبط خیلی کوتاه بود.",
    "Die Belege konnten nicht geladen werden.": "رسیدها بارگذاری نشدند.",
    "Die Bestätigung hat nicht geklappt. Die App-Sperre bleibt aus.": "تأیید کار نکرد. قفل برنامه خاموش می‌ماند.",
    "Die Betriebsdaten werden noch geladen.": "اطلاعات کسب‌وکار هنوز در حال بارگذاری است.",
    "Die Datei ist zu groß.": "فایل خیلی بزرگ است.",
    "Die Datei wurde abgelehnt.": "فایل رد شد.",
    "Die Erlaubnis für Benachrichtigungen fehlt. Bitte in den Handy-Einstellungen für Zunft erlauben.": "مجوز اعلان‌ها موجود نیست. لطفاً در تنظیمات گوشی برای Zunft اجازه دهید.",
    "Die Kamera ist nicht verfügbar. Bitte den Zugriff in den Einstellungen erlauben oder den Code von Hand eintippen.": "دوربین در دسترس نیست. لطفاً در تنظیمات اجازه دسترسی دهید یا کد را دستی تایپ کنید.",
    "Die Karte konnte nicht geöffnet werden.": "نقشه باز نشد.",
    "Die Notiz ist zu lang (höchstens {0} Zeichen).": "یادداشت خیلی طولانی است (حداکثر {0} نویسه).",
    "Die Notiz kann nicht mehr entfernt werden (bereits abgerechnet?).": "یادداشت دیگر قابل حذف نیست (قبلاً صورتحساب شده؟).",
    "Die Notiz konnte nicht gespeichert werden.": "یادداشت ذخیره نشد.",
    "Die Notiz konnte nicht verarbeitet werden.": "یادداشت پردازش نشد.",
    "Die Notizen konnten nicht geladen werden.": "یادداشت‌ها بارگذاری نشدند.",
    "Die Notizen konnten nicht geladen werden. Bitte Internetverbindung prüfen.": "یادداشت‌ها بارگذاری نشدند. لطفاً اتصال اینترنت را بررسی کنید.",
    "Die Pause muss kürzer sein als die Arbeitszeit.": "استراحت باید کوتاه‌تر از زمان کار باشد.",
    "Die Person bekommt wieder Zugang (und belegt einen Platz).": "فرد دوباره دسترسی می‌گیرد (و یک جایگاه را اشغال می‌کند).",
    "Die Person installiert Zunft, registriert sich mit der eigenen E-Mail und scannt diesen Code (oder tippt ihn ein).": "فرد Zunft را نصب می‌کند، با ایمیل خودش ثبت‌نام می‌کند و این کد را اسکن می‌کند (یا تایپ می‌کند).",
    "Die Person kommt sofort nicht mehr in den Betrieb. Ihre Notizen bleiben erhalten. Der Platz wird frei.": "فرد بلافاصله از کسب‌وکار خارج می‌شود. یادداشت‌هایش می‌مانند. جایگاه آزاد می‌شود.",
    "Die Person verliert sofort jede Verbindung zu deinem Betrieb: keine Aufträge, keine Kunden, keine Daten. Ihre bisherigen Notizen bleiben bei den Aufträgen (mit ihrem Namen). Ihr Konto gehört ihr: sie kann damit einen eigenen Betrieb gründen oder einem anderen beitreten. Der Platz wird frei.": "فرد بلافاصله هر ارتباطی با کسب‌وکار شما را از دست می‌دهد: بدون سفارش کار، مشتری و داده. یادداشت‌های قبلی او کنار سفارش‌ها می‌مانند (با نامش). حساب مال خود اوست: می‌تواند کسب‌وکار خودش را راه بیندازد یا به دیگری بپیوندد. جایگاه آزاد می‌شود.",
    "Die Rechnung hat keine Positionen.": "فاکتور قلمی ندارد.",
    "Die Rechnung ist schon als bezahlt markiert. Bitte zuerst mit dem Steuerberater klären, wie sie zu korrigieren ist.": "فاکتور قبلاً به عنوان پرداخت‌شده علامت خورده است. لطفاً ابتدا با مشاور مالیاتی روشن کنید چگونه اصلاح شود.",
    "Die Rechnung konnte nicht storniert werden.": "فاکتور ابطال نشد.",
    "Die Verarbeitung ist fehlgeschlagen.": "پردازش ناموفق بود.",
    "Dienstag": "سه‌شنبه",
    "Diese Notiz gehört zu keinem Auftrag. Bitte verwerfen und neu aufnehmen.": "این یادداشت به هیچ سفارش کاری تعلق ندارد. آن را رها کنید و دوباره ضبط کنید.",
    "Diese Rechnung wurde schon storniert.": "این فاکتور قبلاً ابطال شده است.",
    "Diese Zeit wurde schon abgerechnet und kann nicht gelöscht werden.": "این زمان قبلاً صورتحساب شده و قابل حذف نیست.",
    "Diesen Kunden gibt es schon": "این مشتری از قبل وجود دارد",
    "Dieser Auftrag ist abgerechnet. Es können keine Notizen mehr aufgenommen werden.": "این سفارش کار صورتحساب شده است. دیگر نمی‌توان یادداشت ضبط کرد.",
    "Dieser Auftrag ist abgeschlossen. Es können keine Notizen mehr aufgenommen werden.": "این سفارش کار بسته است. دیگر نمی‌توان یادداشت ضبط کرد.",
    "Dieser Kunde existiert nicht mehr.": "این مشتری دیگر وجود ندارد.",
    "Dieser Kunde hat Angebote oder Rechnungen und kann nicht gelöscht werden (gesetzliche Aufbewahrung).": "این مشتری پیشنهاد یا فاکتور دارد و قابل حذف نیست (نگهداری قانونی).",
    "Dieses Handy hat keine Adresse für Meldungen bekommen. Bitte später noch einmal versuchen.": "این گوشی نشانی‌ای برای اعلان‌ها نگرفت. لطفاً بعداً دوباره تلاش کنید.",
    "Dieses PDF wird gelesen und als Beleg gespeichert.": "این PDF خوانده و به عنوان رسید ذخیره می‌شود.",
    "Dir ist noch kein Auftrag zugewiesen. Sobald der Inhaber oder das Büro dir einen Auftrag zuweist, erscheint er hier.": "هنوز سفارش کاری به شما اختصاص داده نشده. به محض اینکه مالک یا دفتر سفارشی به شما بدهد، اینجا ظاهر می‌شود.",
    "Donnerstag": "پنجشنبه",
    "Du verlierst den Zugang zu allen Aufträgen und Kunden dieses Betriebs. Deine Notizen bleiben dort erhalten. Dein Konto bleibt bestehen: du kannst einen eigenen Betrieb gründen oder einem anderen beitreten.": "دسترسی به همه سفارش‌ها و مشتریان این کسب‌وکار را از دست می‌دهید. یادداشت‌های شما آنجا می‌مانند. حساب شما باقی می‌ماند: می‌توانید کسب‌وکار خودتان را راه بیندازید یا به دیگری بپیوندید.",
    "E-Mail (Betrieb)": "ایمیل (کسب‌وکار)",
    "E-Mail oder Passwort ist falsch.": "ایمیل یا گذرواژه نادرست است.",
    "E-Rechnung": "فاکتور الکترونیکی",
    "EUR": "EUR",
    "Ein Angebot ist keine Rechnung.": "پیشنهاد قیمت فاکتور نیست.",
    "Ein Betrieb kann nicht mit einem Tipp gelöscht werden: Rechnungen müssen gesetzlich über Jahre aufbewahrt werden (GoBD). Wenn du deinen Betrieb schließen oder dein Konto löschen möchtest, wende dich bitte an den Support. Mitarbeiter kannst du unter „Team“ entfernen.": "یک کسب‌وکار با یک ضربه حذف نمی‌شود: فاکتورها طبق قانون باید سال‌ها نگهداری شوند (GoBD). اگر می‌خواهید کسب‌وکار را ببندید یا حساب را حذف کنید، لطفاً با پشتیبانی تماس بگیرید. کارکنان را می‌توانید زیر «تیم» حذف کنید.",
