    "Erstellt": "صادرشده",
    "Es wird eine Stornorechnung mit eigener Nummer erstellt, die diese Rechnung aufhebt. Die Rechnung selbst bleibt unverändert gespeichert und wird als „Storniert“ markiert.\n\nDie Notizen des Auftrags werden wieder frei. Danach kannst du den Auftrag erneut prüfen, korrigieren und eine neue Rechnung erstellen.\n\nDas kann nicht rückgängig gemacht werden.": "یک اعتبارنامه با شماره مخصوص ایجاد می‌شود که این فاکتور را باطل می‌کند. خود فاکتور بدون تغییر ذخیره می‌ماند و «ابطال‌شده» علامت می‌خورد.\n\nیادداشت‌های سفارش کار دوباره آزاد می‌شوند. پس از آن می‌توانید سفارش کار را دوباره بررسی و اصلاح کنید و فاکتور جدیدی بسازید.\n\nاین کار قابل بازگشت نیست.",
    "Es wurde nichts aufgenommen.": "چیزی ضبط نشد.",
    "Fast geschafft: Wir haben dir eine E-Mail geschickt. Bitte bestätige die Adresse und melde dich dann an.": "تقریباً تمام است: ایمیلی برایتان فرستادیم. لطفاً نشانی را تأیید کنید و سپس وارد شوید.",
