    "Für die E-Rechnung fehlt die IBAN des Betriebs (Betrieb → Bearbeiten).": "برای فاکتور الکترونیکی IBAN کسب‌وکار موجود نیست (کسب‌وکار ← ویرایش).",
    "Für die E-Rechnung fehlt die Steuernummer oder USt-IdNr. des Betriebs.": "برای فاکتور الکترونیکی شماره مالیاتی یا شناسه مالیات بر ارزش افزوده کسب‌وکار موجود نیست.",
