    "Noch keine Notizen. Nimm eine Notiz auf (oder tippe sie ein): Arbeitszeit, Material, Besonderheiten. Du kannst beliebig viele Notizen machen, auch an mehreren Tagen.": "هنوز یادداشتی نیست. یادداشتی ضبط کنید (یا بنویسید): زمان کار، مصالح، نکات خاص. می‌توانید هر تعداد یادداشت بگذارید، در چند روز هم.",
